import React from 'react'
import Masonary,{ResponsiveMasonry}  from 'react-responsive-masonry';
import galleryImages from './galleryImage';
const MyGalllery = () => {
  return (
    <ResponsiveMasonry columnsCountBreakPoints={{350:1,768:3,992:4}}>
        <Masonary gutter='1rem'>
            {
                galleryImages.map((item,index) =>{
                    <img src={item} alt="" style={
                        {'width':'100%','display':'block','borderRadius':'10px'}} />
                })
            }
        </Masonary>

    </ResponsiveMasonry>
  )
}

export default MyGalllery
